@import url("https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,600;0,700;1,500&family=Inter:wght@400;500;600;700&display=swap");
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

.sl-app {
  --ink: #0A1F19;
  --paper: #F5F2EA;
  --card: #FFFFFF;
  --line: #E3DCCB;
  --line-soft: #EDE7D9;
  --text: #1F2823;
  --muted: #8A8574;
  --gold: #B08A3C;
  --gold-bright: #D8B45E;
  --gold-soft: rgba(176, 138, 60, 0.12);
  --green: #175243;
  --green-soft: rgba(23, 82, 67, 0.08);
  display: flex;
  height: 100vh;
  background: var(--paper);
  color: var(--text);
  font-family: "Inter", sans-serif;
}

.sidebar {
  width: 250px;
  background: var(--ink);
  color: #F3EFE4;
  display: flex;
  flex-direction: column;
}

.brand-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 22px 20px;
  border-bottom: 1px solid rgba(243, 239, 228, 0.08);
}

.brand-tile {
  width: 40px;
  height: 40px;
  border-radius: 11px;
  background: linear-gradient(135deg, var(--gold-bright), var(--gold));
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.brand-tile svg {
  width: 20px;
  height: 20px;
  color: var(--ink);
}

.brand-text {
  display: flex;
  flex-direction: column;
}

.brand-name {
  font-family: "Playfair Display", serif;
  font-size: 15px;
  font-weight: 700;
}

.brand-tag {
  font-size: 9px;
  color: var(--gold-bright);
  text-transform: uppercase;
  letter-spacing: 0.14em;
  margin-top: 2px;
}

.nav-menu {
  list-style: none;
  padding: 12px 12px;
  flex: 1;
  overflow-y: auto;
}

.nav-group {
  margin-bottom: 6px;
}

.nav-section-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 14px 6px;
  font-size: 9px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: rgba(243, 239, 228, 0.35);
  cursor: pointer;
  user-select: none;
  transition: color 0.2s;
}

.nav-section-head:hover {
  color: rgba(243, 239, 228, 0.65);
}

.nav-section-head::after {
  content: "";
  width: 7px;
  height: 7px;
  border-right: 1.5px solid currentColor;
  border-bottom: 1.5px solid currentColor;
  transform: rotate(45deg);
  transition: transform 0.2s;
}

.nav-group.collapsed .nav-section-head::after {
  transform: rotate(-45deg);
}

.nav-group-items {
  list-style: none;
}

.nav-group.collapsed .nav-group-items {
  display: none;
}

.nav-item {
  position: relative;
  padding: 10px 14px;
  margin-bottom: 3px;
  border-radius: 8px;
  cursor: pointer;
  font-size: 13px;
  font-weight: 500;
  color: rgba(243, 239, 228, 0.6);
  transition: all 0.2s;
}

.nav-item:hover {
  background: rgba(243, 239, 228, 0.06);
  color: #F3EFE4;
}

.nav-item.active {
  background: linear-gradient(90deg, rgba(216, 180, 94, 0.16), transparent);
  color: var(--gold-bright);
}

.nav-item.active::before {
  content: "";
  position: absolute;
  left: 0;
  top: 22%;
  height: 56%;
  width: 3px;
  border-radius: 3px;
  background: var(--gold);
}

.sidebar-footer {
  padding: 14px;
  border-top: 1px solid rgba(243, 239, 228, 0.08);
}

.logout-btn {
  width: 100%;
  padding: 10px;
  background: transparent;
  border: 1px solid rgba(243, 239, 228, 0.15);
  border-radius: 8px;
  color: rgba(243, 239, 228, 0.6);
  font-size: 12px;
  font-weight: 500;
  font-family: "Inter", sans-serif;
  cursor: pointer;
  transition: all 0.2s;
}

.logout-btn:hover {
  border-color: var(--gold);
  color: var(--gold-bright);
}

.main {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.topbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 18px 28px;
  border-bottom: 1px solid var(--line);
}

.topbar-kicker {
  font-size: 9px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.16em;
  color: var(--gold);
}

.topbar h2 {
  font-family: "Playfair Display", serif;
  font-size: 22px;
  font-weight: 700;
  margin-top: 2px;
}

.user-chip {
  display: flex;
  align-items: center;
  gap: 12px;
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 8px 14px;
}

.user-avatar {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: var(--green);
  color: #F1E8D2;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
  font-weight: 700;
}

.user-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.user-info #userEmail {
  font-size: 12px;
  font-weight: 600;
}

.role-badge {
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--gold);
}

.content {
  flex: 1;
  padding: 26px 28px;
  overflow-y: auto;
}

